{
  "name": "harborlight",
  "version": "1.0.0",
  "private": true,
  "description": "Tiny notice dispatcher. Customer notices use an outbox. A separate legacy sender talks to an older provider.",
  "main": "index.js",
  "scripts": {
    "test": "node --test src/notifications/dispatch.test.js src/notifications/legacy/sender.test.js"
  }
}

const { sendDirect, countFor } = require("../../outbox");

function handle(event) {
  if (event.type === "legacy.alert") {
    return sendDirect(event.type, event.data);
  }
  return null;
}

module.exports = { handle, countFor };

const { dispatchOnce, countFor } = require("../outbox");

function handle(event) {
  if (event.type === "notice.created") {
    return dispatchOnce(event.id, event.type, event.data);
  }
  return null;
}

module.exports = { handle, countFor };

const assert = require("node:assert/strict");
const test = require("node:test");
const { handle, countFor } = require("./sender");

test("legacy.alert colliding provider ids both send", () => {
  handle({ id: "evt_legacy_same", type: "legacy.alert", data: { n: 1 } });
  handle({ id: "evt_legacy_same", type: "legacy.alert", data: { n: 2 } });
  assert.equal(countFor("legacy.alert"), 2);
});

test("legacy.ping is not routed yet", () => {
  const event = { id: "evt_ping_pending", type: "legacy.ping", data: { n: 1 } };
  assert.equal(handle(event), null);
  assert.equal(countFor("legacy.ping"), 0);
});

const sent = [];
const byKey = new Map();

function dispatchOnce(eventId, channel, body) {
  const hit = byKey.get(eventId);
  if (hit) return hit;
  const row = Object.freeze({
    seq: sent.length,
    eventId,
    channel,
    body,
    status: "sent",
  });
  sent.push(row);
  byKey.set(eventId, row);
  return row;
}

function sendDirect(channel, body) {
  const row = Object.freeze({
    seq: sent.length,
    eventId: null,
    channel,
    body,
    status: "sent",
  });
  sent.push(row);
  return row;
}

function deliveries() {
  return sent.slice();
}

function countFor(channel) {
  let n = 0;
  for (const row of sent) {
    if (row.channel === channel) n += 1;
  }
  return n;
}

module.exports = { dispatchOnce, sendDirect, deliveries, countFor };

const assert = require("node:assert/strict");
const test = require("node:test");
const { handle, countFor } = require("./dispatch");

test("notice.created duplicate delivery does not double-notify", () => {
  const event = {
    id: "evt_notice_1",
    type: "notice.created",
    data: { to: "ops@harborlight.test" },
  };
  handle(event);
  handle(event);
  assert.equal(countFor("notice.created"), 1);
});

